/** Synchronous privacy identity: asynchronous thumbnail callbacks read this
 *  directly, not a React closure that can lag a takeover event. */
export function thumbnailFence(bot: RosterRow): string {
  const state = screenStateFor($screenState.get(), bot)
  const lease = state?.lease
  const status = state?.status

  return JSON.stringify([status?.mode ?? 'native', status?.endpoint_fingerprint,
    status?.authority, status?.endpoint_generation, lease?.authority,
    lease?.phase, lease?.holder, lease?.epoch, lease?.endpoint_identity])
}

