def _screen_external(args) -> int:
    from tools.bot_desktop import external, lease, lease_external
    try:
        if args.computer_use_screen_action == "external-initialize":
            result = {"lease": lease.public_view(external.initialize_excluded()),
                      "operation": "excluded_initialization", "active_owner_granted": False}
            rc = 0  # Preparation succeeded, not an active-owner result.
        else:
            result = lease_external.reconcile(
                aggregate_recovery=args.computer_use_screen_action == "external-recover")
            rc = 0 if result.get("active_owner_granted") is True else 1
    except (OSError, ValueError, TypeError, external.ExternalScreenError) as exc:
        result = {"phase": "excluded", "active_owner_granted": False,
                  "code": getattr(exc, "code", "external_screen_excluded"), "reason": str(exc)}
        rc = 1
    if bool(getattr(args, "json", False)):
        print(json.dumps(result, sort_keys=True, indent=2))
    else:
        print("External Screen: " + str(result.get("reason") or result.get("operation")))
        print("  active ownership " + ("granted" if result.get("active_owner_granted") is True else "not granted"))
    return rc


def _screen_generation(args) -> int:
    from tools.bot_desktop import external, generation
    try:
        result = generation.status()
        rc = 0
    except (OSError, ValueError, TypeError, KeyError, external.ExternalScreenError) as exc:
        result = {"phase": "excluded", "active_owner_granted": False,
                  "code": "generation-excluded", "reason": str(exc)}
        rc = 1
    if bool(getattr(args, "json", False)):
        print(json.dumps(result, sort_keys=True, indent=2))
    else:
        print("External Screen generation: " + str(result.get("operation") or result.get("reason") or "inspection only"))
    return rc


